---@param dic table<number, ExhibitData> @展品数据组
function ExhibitBuilderManager:BuildMoreExhibit(dic,carCount)
    local count,finishcount=0,0

    ---@param exhibitBuilder ExhibitBuilder
    ---@param exhibitData ExhibitData
    local finishEvt = function(exhibitBuilder,exhibitData)
        if exhibitData:GetType() == ExhibitType.Trophy then
            self:TrophyDecorate(exhibitBuilder,exhibitData)
        end
        finishcount=finishcount+1
        PersonalHomeDataManager:Get():UpdatePersonalLoading(finishcount/count*(1-0.14*carCount))
        if finishcount == count then
            logError("开始组装家具")
            self:Assemble()
            UINotify:Get():SendNotification(UINotifyEvent.PersonalHomeExhibitAssembleOver)
        end
    end
    local paramList={}
    for i, exhibitData in pairs(dic) do
        count=count+1
        ---@type ExhibitBuilderParam
        local param = ExhibitBuilderParam()
        param.exhibitID = exhibitData:GetExhibitID()
        param.serverID = exhibitData:GetServerID()
        param.finishEvt = finishEvt
        param.finishParam = exhibitData
        paramList[i]=param
    end
    for i, exhibitData in pairs(dic) do
        local builderId = self:BuildExhibit(paramList[i])
        exhibitData:SetExhibitBuilderId(builderId)
    end
end

---@param exhibitData ExhibitData
function ExhibitBuilderManager:BuilderOneExhibit(exhibitData,endFunc)
    local param = ExhibitBuilderParam()
    param.exhibitID = exhibitData:GetExhibitID()
    param.serverID = exhibitData:GetServerID()
    param.finishParam =exhibitData
    ---@param exhibitBuilder ExhibitBuilder
    ---@param exhibitData ExhibitData
    param.finishEvt = function(exhibitBuilder,exhibitData)
        if exhibitData:GetType() == ExhibitType.Trophy then
            self:TrophyDecorate(exhibitBuilder,exhibitData)
        end
        if endFunc then
            endFunc(exhibitBuilder,exhibitData)
        end
    end
    exhibitData:SetExhibitBuilderId(self:BuildExhibit(param))
end


---@param param ExhibitBuilderParam
function ExhibitBuilderManager:BuildExhibit(param)

    ---@type ExhibitBuilder
    local result = self:SampleBuilder(param)
    if result == nil then
        logError("---   Error:ExhibitBuilder = nil")
        return -1
    end

    if result:GetProgress() >= 1 then
        result:BuilderExhibit()
    else
        logError("---   Error:展品没加载完，重复加载，检查数据")
    end
    self.BuilderDic[result.ID] = result
    return result.ID
end

---@param param ExhibitBuilderParam
function ExhibitBuilderManager:SampleBuilder(param)
    ---@type ExhibitBuilder
    local result
    if #self.BuilderCache > 0 then
        result = self.BuilderCache[1]
        table.remove(self.BuilderCache, 1)
    else
        result = ExhibitBuilder()
    end
    result:SetParam(param)
    self.BuilderDic[result.ID] = result
    return result
end

----根据Id 回收builder
---@param ID ExhibitBuilder
function ExhibitBuilderManager:DestroyCache()
    for id, builder in pairs(self.BuilderCache) do
        if builder ~= nil then
            builder:Recycle(true)
            self.BuilderCache[id] = nil
        end
    end
end

----根据Id 回收builder
---@param ID ExhibitBuilder
function ExhibitBuilderManager:Recycle(ID, isDestroy)
    local builder = self.BuilderDic[ID]
    if builder == nil then
        return
    end
    self.BuilderDic[ID] = nil
    table.insert(self.BuilderCache, builder)
    builder:Recycle(isDestroy)
end


---@param dic table<number, ExhibitData> @展品数据组
function ExhibitBuilderManager:Assemble()
    ---@type ExhibitData
    local exhibitRoot = PersonalHomeDataManager:Get():GetPersonalHomeData():GetRootExhibit()
    ---@type ExhibitBuilder
    local exhibitBuilder = self:GetBuilderById(exhibitRoot:GetExhibitBuilderId())
    UIUtil.SetParentTransform(PersonalHomeDataManager:Get():GetRootScene(),exhibitBuilder:GetRoot(),false)
    CS.UIUtil.LocalPosition(exhibitBuilder:GetRoot().transform,Vector3.zero)
    CS.UIUtil.LocalRotation(exhibitBuilder:GetRoot().transform,Quaternion.identity)
    CommonHelper:CSGameObjectSetActive(exhibitBuilder:GetRoot(),true)
    exhibitRoot:GetChildDic()
    self:SetExhibitSiteInfo(exhibitRoot,exhibitBuilder)

end

---@param exhibitData ExhibitData
---@param exhibitBuilder ExhibitBuilder
function ExhibitBuilderManager:SetExhibitSiteInfo(exhibitData, exhibitBuilder)
    local personalHomeData = PersonalHomeDataManager:Get():GetPersonalHomeData()
    ---@type  table<number,number> @展示品子节点<slot,ID>
    local dic = exhibitData:GetChildDic()
    for slot, serverID in pairs(dic) do
        if serverID>0 then
            local childExhibitData = personalHomeData:GetExhibitByServerID(serverID)
            local childExhibitBuilder = self:GetBuilderById(childExhibitData:GetExhibitBuilderId())
            ---@type ExhibitBoxInfo
            local boxInfo = ExhibitBoxMgr:Get():GetBoxInfoByServerIdSlot(exhibitData:GetServerID(),slot)
            if boxInfo then
                boxInfo:SetDepositServerID(serverID)
                local parent= exhibitBuilder:GetSlotBoxRootBySlot(slot)
                if parent~=nil then
                    UIUtil.SetParentTransform(parent,childExhibitBuilder:GetRoot() ,true)
                    CommonHelper:CSGameObjectSetActive(childExhibitBuilder:GetRoot() ,true)
                    self:SetExhibitSiteInfo(childExhibitData,childExhibitBuilder)
                end

            end
        end
    end
end

